r2ah/93-cognito-explicit-client-bindings.handler.js:
const {CognitoIdentityProviderClient,InitiateAuthCommand}=require('@aws-sdk/client-cognito-identity-provider');
const client=new CognitoIdentityProviderClient({});
exports.handler=async(event)=>{
 const args={USERNAME:'synthetic',PASSWORD:'synthetic'};
 const result=event.pathParameters.realm==='staff'
 ? await client.send(new InitiateAuthCommand({ClientId:process.env.STAFF_CLIENT_ID,AuthFlow:'USER_PASSWORD_AUTH',AuthParameters:args}))
 : await client.send(new InitiateAuthCommand({ClientId:process.env.AUTH_CLIENT_ID,AuthFlow:'USER_PASSWORD_AUTH',AuthParameters:args}));
 return {statusCode:200,body:JSON.stringify(result)};
};
